/**
 * Gemini Watermark Size and Dimension Catalog
 * Derived from official Gemini 2.0 / 2.5 / 3.x and Veo output specifications.
 */

export interface WatermarkConfig {
  logoSize: number;
  marginRight: number;
  marginBottom: number;
  variant?: string;
  description?: string;
}

export interface DimensionEntry {
  aspectRatio: string;
  width: number;
  height: number;
  tier: '0.5k' | '1k' | '2k' | '4k';
  config: WatermarkConfig;
}

