/**
 * Predicts watermark configuration based on image/video width and height.
 */
export function detectWatermarkConfig(width: number, height: number): WatermarkConfig {
  // Check exact catalog match
  const exactMatch = OFFICIAL_GEMINI_IMAGE_SIZES.find(
    entry => entry.width === width && entry.height === height
  );
  if (exactMatch) {
    return { ...exactMatch.config, description: `Exact match: ${exactMatch.aspectRatio} (${exactMatch.tier})` };
  }

  // Check aspect ratio tolerance for scaled versions
  const ratio = width / height;
  const closestByRatio = OFFICIAL_GEMINI_IMAGE_SIZES.find(entry => {
    const entryRatio = entry.width / entry.height;
    return Math.abs(ratio - entryRatio) < 0.05 && Math.abs(width - entry.width) < 100;
  });

  if (closestByRatio) {
    return {
      ...closestByRatio.config,
      description: `Inferred from ${closestByRatio.aspectRatio} catalog entry`
    };
  }

  // Heuristic rule based on resolution tier
  const maxDim = Math.max(width, height);
  const minDim = Math.min(width, height);

  if (minDim >= 1024) {
    return {
      logoSize: 96,
      marginRight: 64,
      marginBottom: 64,
      description: 'High-res heuristic (96px, 64px margins)'
    };
  }

  if (maxDim <= 720) {
    return {
      logoSize: 48,
      marginRight: 32,
      marginBottom: 32,
      description: 'Compact heuristic (48px, 32px margins)'
    };
  }

  // Default balanced config
  return {
    logoSize: 48,
    marginRight: 32,
    marginBottom: 32,
    description: 'Standard 48px baseline'
  };
}

/**
 * Computes pixel bounding box for watermark within media of given dimensions.
 */
export function calculateWatermarkBounds(
  width: number,
  height: number,
  config: WatermarkConfig
): { x: number; y: number; width: number; height: number } {
  const x = Math.max(0, width - config.marginRight - config.logoSize);
  const y = Math.max(0, height - config.marginBottom - config.logoSize);

  return {
    x,
    y,
    width: Math.min(config.logoSize, width - x),
    height: Math.min(config.logoSize, height - y)
  };
}
